import{_ as a,H as n,f as s,i as p}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"11 | 幕后复盘：Hermes为什么回答以后还在忙？","description":"","frontmatter":{},"headers":[{"level":2,"title":"那行提示是怎么来的","slug":"那行提示是怎么来的","link":"#那行提示是怎么来的","children":[]},{"level":2,"title":"后台怎么跑","slug":"后台怎么跑","link":"#后台怎么跑","children":[]},{"level":2,"title":"后台到底留了什么","slug":"后台到底留了什么","link":"#后台到底留了什么","children":[]},{"level":2,"title":"自动复盘和手动复盘","slug":"自动复盘和手动复盘","link":"#自动复盘和手动复盘","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"课后题","slug":"课后题","link":"#课后题","children":[]}],"relativePath":"自进化Agent工程实战/11｜幕后复盘：Hermes为什么回答以后还在忙？.md","filePath":"自进化Agent工程实战/11｜幕后复盘：Hermes为什么回答以后还在忙？.md","lastUpdated":1795559729000}'),t={name:"自进化Agent工程实战/11｜幕后复盘：Hermes为什么回答以后还在忙？.md"};function i(r,e,l,o,m,h){return n(),s("div",null,[...e[0]||(e[0]=[p(`<h1 id="_11-幕后复盘-hermes为什么回答以后还在忙" tabindex="-1">11 | 幕后复盘：Hermes为什么回答以后还在忙？ <a class="header-anchor" href="#_11-幕后复盘-hermes为什么回答以后还在忙" aria-label="Permalink to &quot;11 | 幕后复盘：Hermes为什么回答以后还在忙？&quot;">​</a></h1><p>你好，我是 Tyler。</p><p>上一讲结尾，你见过回答之后冒出来的那行 Memory updated。回答都发出去了，Hermes 为什么还在后台忙？</p><p>这一讲我们就来拆解这个机制。回答发出去之后，Hermes 在后台自己做了一件事：把刚才这段经历重新看一遍，挑出以后还用得上的东西。</p><p>后台最核心的工作就是复盘。它把前台跑出来的经历拿回来，改进两类记忆：一类是陈述性记忆，由 Memory 保存，比如用户是谁、环境长什么样；一类是程序记忆，也就是 Skill，比如一类活儿该按什么步骤做。这两类记忆准了，前台下次干活就顺手，产出的经历质量也更高，又供下一轮复盘使用。</p><h2 id="那行提示是怎么来的" tabindex="-1">那行提示是怎么来的 <a class="header-anchor" href="#那行提示是怎么来的" aria-label="Permalink to &quot;那行提示是怎么来的&quot;">​</a></h2><p>这天夜里，支付接口出现错误率告警，你让 Hermes 核对这段时间的应用日志。</p><p>Agent 提交查询，工具却返回零条记录。它怀疑是时间范围没覆盖出错时段，把范围前后各放宽了十分钟，第二次还是空的，于是回复：没有找到告警时段的应用日志，暂时无法从日志侧判断错误来源。</p><p>你没有接受“查不到”的回复：网关已记录大量失败请求，应用侧却两次查不到日志，也许日志没写，也许查错了位置。你记得，支付服务上周刚迁移过日志。旧入口还能查历史记录，但不再接收新的生产日志；新的日志已经写入 payment-api-prod。</p><p>核对工具调用记录可以发现，服务名、时间范围都对，可两次请求都发到了旧入口。这个刚接手的 Agent，还不知道上周的迁移。你补充了一句：支付服务的生产日志已经迁移到payment-api-prod，旧入口只保留迁移前的历史记录，请从新入口重新查询。</p><p>这一次，在同一个告警时段里查到了多条超时记录。Agent 随即更新回答：已在 payment-api-prod 找到告警时段的应用日志。</p><p>你没有再向 Agent 提要求。过了一会儿，回答下面出现那行 Self-improvement review:Memory updated。回答已经发出去了，后台凭什么自己动起来？</p><h2 id="后台怎么跑" tabindex="-1">后台怎么跑 <a class="header-anchor" href="#后台怎么跑" aria-label="Permalink to &quot;后台怎么跑&quot;">​</a></h2><p>前台拿到日志、把回答给了你之后，Hermes 还要做完这一轮的收尾，其中就包括判断要不要安排后台复盘。这就是经典 AI 系统中在线与离线分离的架构：前台在线实时响应用户，后台离线做复盘和学习。</p><p>省略周围的异常处理后，turn_finalizer.py 里的相关代码是这样的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (</span></span>
<span class="line"><span>   final_response</span></span>
<span class="line"><span>   and not interrupted</span></span>
<span class="line"><span>   and (_should_review_memory or _should_review_skills)</span></span>
<span class="line"><span>):</span></span>
<span class="line"><span>   agent._spawn_background_review(</span></span>
<span class="line"><span>       messages_snapshot=list(messages),</span></span>
<span class="line"><span>       review_memory=_should_review_memory,</span></span>
<span class="line"><span>       review_skills=_should_review_skills,</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>final_response 表示已经有了最终回答；not interrupted 要求这一轮没被中断；最后两个标记分别表示本轮是否达到 Memory 或 Skill 的复盘条件。</p><p>这两个标记不是模型读完纠正内容后当场判断的。内置 Memory 可用时，Hermes 按用户对话轮数计数，到了配置的检查间隔就置位；Skill 按主循环迭代次数计数，因为一个要求背后可能跑了好多轮判断和工具调用，它数的不是你发了几条消息。</p><p>我们的例子里，你纠正日志入口的这一轮正好达到 Memory 检查条件。但程序只决定该不该安排一次检查，至于这句话值不值得保存，是后台模型看完会话后再判断的。所以不是每次纠正都会立刻更新 Memory：就算进了复盘，也可能没什么可留。</p><p>只把最后那段回答丢给后台不够：它只说了支付请求在等订单服务返回时超时，不会重提前两次为什么查询记录为空、你又补充了什么迁移信息。后台需要这段完整的查询和纠正过程，才能理解前两次为什么没查到、第三次却查到了。</p><p>Hermes 把当时的会话复制为 messages_snapshot，连同你的要求、工具调用、返回结果和你的纠正，一起交给一个独立的后台实例。</p><p>这份副本和前台是分开的：你之后追加的要求不会进来，后台对话也不写回前台。前台不用等复盘完成，中途失败也不影响已经发出去的结论。复盘在 daemon 线程中运行；进程退出时，尚未完成的复盘可能中止。</p><p>这套机制不保证持久排队和自动重试。企业接入时至少应分别记录触发、实际启动、线程结束、工具调用与回执，以及失败原因，才能区分没有启动、仍在运行、执行失败和正常结束却没有写入。</p><p>为什么要把这件事拆出去？前台回答的是眼下的问题，判断日志有没有找到、接下来该查什么，时间越短越好。后台问的是另一件事：这段经历里，哪些信息值得带到以后？它可能要比较现有记忆，判断是否重复，再决定怎样表述。把这些工作塞在最终回答之前，用户就得为未来可能用上的经验多等一段时间；每轮都做，还会为没有新信息的普通对话反复付出模型调用成本。</p><p>按间隔检查，就是在经验保留的及时性和复盘开销之间做取舍。间隔短，新纠正较早有机会进入记忆，但检查得更频繁；间隔长，后台开销较少，也可能让有价值的信息更晚才被处理。因此，间隔决定的是检查机会，不能代替模型判断经验质量。你不能只把间隔调小，就认为系统一定学得更好。</p><p>会话快照还给这次复盘划定了时间范围。后台只能依据拿到的那份经历判断，你后来补充的新要求，要留给后续处理。如果你在复盘进行时又纠正了刚才的说法，旧快照不会自动获得这次纠正。排查一条记忆为什么被这样写下来时，先核对后台当时看到了哪个版本的会话，比只看此刻聊天窗口里的最新消息更有用。</p><p>配套脚本安排正常完成、关闭自动检查和中途打断三个场景。本练习观察两个阻止触发的条件：一是同时把 Memory 和 Skill 的自动检查间隔设为 0，二是这一轮被你中途打断。Memory间隔为 0 只关闭 Memory 自动检查；Skill 检查条件满足时，仍会触发后台复盘，因为代码连接这两个标记用的是“或”。这两个对照并没有穷尽所有不触发的情况，例如没有最终回答，也不满足这里的条件。</p><p>后台启动后，Hermes 会再创建一个 AI Agent 类的实例。前面讲过的 Agent Loop 在这里又跑了一遍，任务换成了“要不要改 Memory、要不要翻 Skill”。因为后台处理的是已经发生的经历，不用碰生产系统。因此 Hermes 只给它开放 Memory、Skill 的管理和读取工具，查日志、发请求这类能碰生产的工具都不在名单里。</p><p>这也限定了后台能作出的判断。它可以从已有记录里发现“入口已经迁移”，却不能为了让记忆显得完整，自己再去生产环境试几个地址。假如会话里只有“可能迁移了”的猜测，工具结果也没有确认，复盘就缺少把猜测写成长期事实的依据。限制工具之后，后台仍然能整理经验，但不能把一次总结悄悄扩展成另一次业务执行。</p><h2 id="后台到底留了什么" tabindex="-1">后台到底留了什么 <a class="header-anchor" href="#后台到底留了什么" aria-label="Permalink to &quot;后台到底留了什么&quot;">​</a></h2><p>这个场景里，后台留下的是已确认的环境变化：支付服务的生产日志换了入口，只要入口还有效，以后查同一服务都用得上。它调用 Memory 工具，把新入口写进 MEMORY.md：</p><ul><li>支付服务的生产日志已迁移到 payment-api-prod。以后查询新的生产日志时使用该入口；旧入口只保留迁移前的历史记录。</li></ul><p>这里没有当晚的请求编号，也没把“订单服务超时”写成以后默认的根因，留下的只是下一次查询用得上的一条事实。</p><p>几天以后，支付服务再次告警。你用同一套配置开了新会话，只说一句：检查告警时段的支付服务日志。你没重提迁移，而 Agent 的第一条查询就用了 payment-api-prod，直接拿到日志，没有再去旧入口查两次空结果。</p><p>新会话启动时，Hermes 会把保存的 Memory 读进模型输入。它没重新训练模型，也没搬上次的完整对话，只是让这条确认过的新入口在任务一开始就可见。</p><p>这里可以把观察拆开：文件里出现新入口，说明信息被保存了；新会话的模型输入里出现这条记忆，说明信息被提供给模型了；第 1 条查询真的使用新入口，才说明它影响了行动。只看到Memory updated，最多能确认复盘报告了更新，不能跳过后面的使用过程，直接说 Agent 已经掌握了这条经验。</p><p>做实验时，最好保留更新前后的记忆文本，再记下新会话的首次工具参数。这样就能看清，省掉前面那几次无效查询，究竟是不是这条记忆起了作用。也别在新会话的提问里再次写出正确入口，否则 Agent 可能只是照着当前要求执行，你就分不清长期记忆有没有帮忙了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/11/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/11/1.png" alt=""></a></p><h2 id="自动复盘和手动复盘" tabindex="-1">自动复盘和手动复盘 <a class="header-anchor" href="#自动复盘和手动复盘" aria-label="Permalink to &quot;自动复盘和手动复盘&quot;">​</a></h2><p>接进在线系统，请求量大，你盯不过来，就让 Agent 按固定间隔自动复盘，同时定期核对复盘有没有正常完成、存储的信息准不准。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/11/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/11/2.png" alt=""></a></p><p>想主动复盘当前会话，敲一个 /refine 就行。碰到重要经验，别等下一次自动检查，当场/refine 一次。</p><p>直接输入 /refine，可以主动安排一次复盘，仍然需要模型决定哪些内容值得留下。你可以在重要任务结束后确认这次检查的结果，却不必把每一轮普通任务都变成人工盯守的复盘流程。日常更适合关注几类现象：该触发时有没有启动，启动后有没有完成，保存的信息是否在后续同类任务中被正确采用。前台一直能回答、后台却长期没有完成过检查，同样值得查清。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>学到这里，我们做个总结吧。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/11/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/11/3.png" alt=""></a></p><p>这一讲我们认识了后台复盘。前台回答一发出，Hermes 会在后台把这段经历重新看一遍，把值得留下的沉淀成记忆：一类记用户和环境，一类记做事的方法。从这一讲起，Agent 第一次不只是完成任务，还能从自己干过的活里长出本事。经历变成记忆，记忆让下一次的前台做得更好，更好的前台又产出更高质量的经历。这是自进化闭环的第一步，后面很多讲，都是在这个闭环上做文章。</p><p>复盘还有个容易被忽略的设计：它不占前台的时间，也不保证每条经历都存住。这不是偷懒，而是取舍。进化不能妨碍生产，后台慢慢学，前台才敢一直转；你只要在关键时刻核对线程、工具回执和文件变化，就能确认它学得靠不靠谱。</p><p>不过，存进去不等于一直是对的。环境一变，记忆就可能过时，甚至记错。到那时候，Hermes 怎么修正自己？下一讲就讲这个。</p><h2 id="课后题" tabindex="-1">课后题 <a class="header-anchor" href="#课后题" aria-label="Permalink to &quot;课后题&quot;">​</a></h2><p>观察题：一句随口的纠正，最后走到哪一步？</p><p>在自己的 Hermes 测试环境里安排一个小任务，中途纠正 Agent 对某个事实的错误理解，这条事实已经核实、以后还会用到，你不主动要求它记住。记录前台返回和后台复盘的时序，看后台有没有启动、有没有调用 Memory 工具写入，核对 MEMORY.md 的变化。</p><p>这一轮结束后，先确认复盘有没有触发。如果触发了，等它跑完，再用同一套配置开新会话做同类任务，不再重复那条纠正，看 Agent 有没有采用新事实。不管最后是没触发、复盘了没写入、写入了新会话没用上，还是成功写入并被采用，都按实际记录写下来。</p><p>思考题：复盘已启动，记忆文件为什么没有变化？会话包含已核实、后续仍有价值的新事实，后台复盘已启动，但记忆文件没有变化。怎样区分已有等价记忆、模型漏记和执行失败？</p><p>期待你在留言区积极发言，分享见解。如果今天的内容对你有启发，欢迎分享给身边更多朋友。</p>`,55)])])}const c=a(t,[["render",i]]);export{d as __pageData,c as default};
